#!/usr/bin/env python3
# luxarch:no-unbounded-waiter hook v1 - DO NOT edit this file - it is emitted by `luxarch --emit hooks`; re-emit to update.
"""Deny a background wait loop with no time limit.

PreToolUse(Bash): deny `run_in_background` on a command that runs `until` or `while` with a `sleep`
and no `timeout` anywhere in it. Such a loop runs until the session ends if what it waits for never
comes: a file in scratch that was cleared, a job that died. Every background task shows as work in
progress, so the owner cannot tell it from real work, and a subagent that started one stays running
until it exits. One ran 38 hours after its file was gone, through two compacts and a close-out.

A background command already notifies the session when it exits, so most waiters need not exist. Where
one must, `timeout 1800 sh -c '...'` bounds it. Quoted text and heredocs are data, not a loop. A wait
written in Python or another language is not read. A command this hook cannot read is denied.
"""

from __future__ import annotations

import re
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).parent))
from _cmdtext import executable_segments, guarded, load_event, text_field, tool_input

_LOOP = re.compile(r"(?:^|[\s;&|(])(?:until|while)\s")
_SLEEP = re.compile(r"(?:^|[\s;&|(])sleep\s")
_TIMEOUT = re.compile(r"(?:^|[\s;&|(/])g?timeout\s")


def main() -> int:
    event = tool_input(load_event())
    command = text_field(event, "command")  # a command that is not text is denied here
    if event.get("run_in_background") is not True:
        return 0
    # A loop's parts are separate segments (`until x`, `do sleep 5`, `done`), so they are read together.
    masked = "\n".join(m for m, _raw in executable_segments(command))
    if _TIMEOUT.search(masked) or not (_LOOP.search(masked) and _SLEEP.search(masked)):
        return 0
    print(
        "DENIED: a background wait loop needs a time limit. If what it waits for never comes, it runs "
        "until the session ends and reads as work still going on, and a subagent that started it "
        "never finishes.\n"
        "A background command already notifies you when it exits, so first ask whether this needs "
        "to exist. If it does, bound it: timeout 1800 sh -c '<the loop>'",
        file=sys.stderr,
    )
    return 2


sys.exit(guarded(main, "no-unbounded-waiter"))
